// spec: specs/buyer-request-guest.md (1.1–1.4) · кейсы: .qa/tests/buyer-request-guest/BUYREQ-GUEST-01.md, -02.md
// seed: tests/seed.spec.ts (гость) · ПРОД, без записи: все не-GET запросы перехватываются.
import { test, expect } from '@playwright/test';
import { FIELDS, NO_ACCESS, interceptWrites, openAsGuest, submitButton } from './buyer-request-guest.helpers';

test.use({ storageState: { cookies: [], origins: [] }, serviceWorkers: 'block' });

async function formOpen(page: import('@playwright/test').Page) {
  const ctl = await interceptWrites(page);
  await openAsGuest(page);
  for (const label of FIELDS) {
    await expect(page.locator('label').filter({ hasText: label }).first(), `поле «${label}»`).toBeVisible();
  }
  await expect(submitButton(page), '«פרסם בקשה» активна').toBeEnabled();
  await expect(page.getByText(NO_ACCESS), 'нет «אין לך הרשאה»').toHaveCount(0);
  expect(ctl.inserts, 'ничего не отправлено').toEqual([]);
}

async function emptySubmit(page: import('@playwright/test').Page) {
  const ctl = await interceptWrites(page);
  await openAsGuest(page);
  await submitButton(page).click();
  await expect(page.getByText('יש להזין מספר טלפון'), 'ошибка обязательного телефона').toBeVisible();
  await expect(page.locator('#title'), '«כותרת הבקשה» подсвечена').toHaveClass(/border-red-500/);
  await expect(page.locator('#contact_phone'), '«טלפון ליצירת קשר» подсвечен').toHaveClass(/border-red-500/);
  await expect(page).toHaveURL(/\/postbuyerrequest/);
  expect(ctl.inserts, 'пустая форма не отправлена').toEqual([]);
  expect(ctl.unexpected, 'других запросов на запись нет').toEqual([]);
}

test.describe('מה אני מחפש לקנות? — гость без входа', () => {
  test('Гость открывает /postbuyerrequest: форма со всеми полями, без перехода на вход #da55b1 @desktop @prod-safe', async ({ page }) => {
    await formOpen(page);
  });

  test('Телефон: гость открывает /postbuyerrequest — форма доступна #da55b1 @android @prod-safe', async ({ page }) => {
    await formOpen(page);
  });

  test('Гость: пустая форма не отправляется — подсвечены «כותרת הבקשה» и «טלפון ליצירת קשר» #da55b1 @desktop @prod-safe', async ({ page }) => {
    await emptySubmit(page);
  });

  test('Телефон: гость — пустая форма не отправляется #da55b1 @android @prod-safe', async ({ page }) => {
    await emptySubmit(page);
  });
});
